// Decides the input type (youtube | upload) and validates it.
// Never throws: invalid input becomes { status: 'error', error } so the user sees a clear message.
const item = $input.first();
const binary = item.binary || {};
const keys = Object.keys(binary);
const url = String(item.json.youtubeUrl || item.json['YouTube URL'] || '').trim();
const fail = (msg, extra) => [{ json: Object.assign({ status: 'error', sourceType: 'invalid', title: '', source: url || 'No input', transcript: '', error: msg }, extra || {}) }];

if (url && keys.length) {
  return fail('Please provide either a YouTube URL or an MP4 video, not both.');
}
if (!url && !keys.length) {
  return fail('No input received. Paste a YouTube URL or upload an MP4 video.');
}

if (url) {
  if (!/^(https?:\/\/)?((www|m|music)\.)?(youtube\.com|youtu\.be)\//i.test(url)) {
    return fail('That does not look like a YouTube link. Use a URL like https://www.youtube.com/watch?v=VIDEO_ID or https://youtu.be/VIDEO_ID');
  }
  const patterns = [
    /[?&]v=([A-Za-z0-9_-]{11})/,
    /youtu\.be\/([A-Za-z0-9_-]{11})/,
    /\/(?:shorts|embed|live|v)\/([A-Za-z0-9_-]{11})/,
  ];
  let videoId = '';
  for (const p of patterns) {
    const m = url.match(p);
    if (m) { videoId = m[1]; break; }
  }
  if (!videoId) {
    return fail('Could not find a video ID in that YouTube URL. Make sure it links to a single video, not a channel or playlist.');
  }
  return [{ json: {
    status: 'ok',
    sourceType: 'youtube',
    videoId: videoId,
    youtubeUrl: 'https://www.youtube.com/watch?v=' + videoId,
    source: 'https://www.youtube.com/watch?v=' + videoId,
  } }];
}

// Uploaded file
const key = keys[0];
const file = binary[key];
const fileName = file.fileName || 'video.mp4';
const mime = String(file.mimeType || '').toLowerCase();
if (!fileName.toLowerCase().endsWith('.mp4') && mime !== 'video/mp4') {
  return fail('Unsupported file format (' + (mime || fileName) + '). Please upload an MP4 video.', { source: fileName });
}
const buffer = await this.helpers.getBinaryDataBuffer(0, key);
const sizeMb = buffer.length / (1024 * 1024);
if (buffer.length === 0) {
  return fail('The uploaded file is empty.', { source: fileName });
}
if (sizeMb > 25) {
  return fail('The video is ' + sizeMb.toFixed(1) + ' MB. The maximum is 25 MB (speech-to-text API limit). Trim or compress it and try again.', { source: fileName });
}
return [{
  json: { status: 'ok', sourceType: 'upload', fileName: fileName, source: fileName, sizeMb: Number(sizeMb.toFixed(2)) },
  binary: { audio: Object.assign({}, file, { fileName: fileName, mimeType: 'video/mp4' }) },
}];

// Free YouTube oEmbed lookup: gives the title and detects private / removed videos
// before spending transcript-API credits.
const input = $('Validate Input').first().json;
const res = $input.first().json;
const code = Number(res.statusCode || 0);
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
const base = { sourceType: 'youtube', videoId: input.videoId, youtubeUrl: input.youtubeUrl, source: input.youtubeUrl, transcript: '' };
if (code === 200 && body && body.title) {
  return [{ json: Object.assign(base, { status: 'ok', title: body.title, author: body.author_name || '' }) }];
}
let error = 'Could not look up this YouTube video (HTTP ' + (code || 'no response') + ').';
if (code === 401 || code === 403) error = 'This video is private or embedding is restricted, so its captions cannot be retrieved.';
if (code === 404 || code === 400) error = 'Video not found. It may have been removed, or the URL/video ID is wrong.';
if (code === 429) error = 'YouTube is rate limiting requests. Please wait a minute and try again.';
return [{ json: Object.assign(base, { status: 'error', title: '', error: error }) }];

// Maps the Supadata response (or an upstream access error) to the shared shape:
// { status, sourceType, title, source, transcript, error }
const meta = $('Check Video Access').first().json;
const res = $input.first().json;
const out = (status, transcript, error) => [{ json: {
  status: status, sourceType: 'youtube', title: meta.title || ('YouTube video ' + meta.videoId), source: meta.youtubeUrl,
  transcript: transcript, error: error || '',
} }];
// False branch of "Video Accessible?": pass the error through
if (res.statusCode === undefined && res.status === 'error') {
  return out('error', '', res.error);
}
const code = Number(res.statusCode || 0);
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = { content: body }; } }
body = body || {};
const apiMsg = body.message || body.details || body.error || '';
if (code === 200) {
  let text = body.content;
  if (Array.isArray(text)) text = text.map(c => c.text || '').join(' ');
  text = String(text || '').replace(/\[(music|applause|laughter)\]/gi, ' ').replace(/\s+/g, ' ').trim();
  if (!text) return out('error', '', 'This video has no captions/subtitles available, so no transcript could be retrieved. Try uploading the video as an MP4 instead.');
  return out('ok', text, '');
}
if (code === 202 || body.jobId) return out('error', '', 'The transcript service queued this video as a background job. Please try again in a minute.');
if (code === 206) return out('error', '', 'No captions/subtitles are available for this video. Try uploading the video as an MP4 instead.');
if (code === 401) return out('error', '', 'Transcript API key is missing or invalid. Check the Supadata credential in n8n.');
if (code === 402) return out('error', '', 'Your Supadata plan does not allow this request (payment required / credits used up).');
if (code === 403) return out('error', '', 'This video is private or restricted, so its captions are not accessible.');
if (code === 404) return out('error', '', 'Video or transcript not found.');
if (code === 429) return out('error', '', 'Transcript API rate limit or monthly quota reached. Please wait and try again later.');
return out('error', '', 'Transcript API error (HTTP ' + (code || 'no response') + ')' + (apiMsg ? ': ' + apiMsg : '.'));

// Gemini has a large context window, so chunks are big. Very long transcripts are split
// at sentence/word boundaries, each chunk summarized, then the section summaries merged.
const text = String($input.first().json.transcript || '').trim();
const MAX = 120000;      // ~30k tokens per chunk
const MAX_CHUNKS = 10;   // ~1.2M characters, many hours of speech
const chunks = [];
let rest = text;
while (rest.length > MAX) {
  let cut = rest.lastIndexOf('. ', MAX);
  if (cut < MAX * 0.5) cut = rest.lastIndexOf(' ', MAX);
  cut = cut < MAX * 0.5 ? MAX : cut + 1;
  chunks.push(rest.slice(0, cut).trim());
  rest = rest.slice(cut).trim();
}
if (rest) chunks.push(rest);
const used = chunks.slice(0, MAX_CHUNKS);
return used.map((chunk, index) => ({ json: {
  chunk: chunk,
  index: index,
  totalChunks: used.length,
  truncated: chunks.length > MAX_CHUNKS,
} }));

