// Collects one Gemini summary per transcript section and explains failures in plain language.
const getText = (j) => {
  if (!j) return '';
  if (typeof j.mergedResponse === 'string' && j.mergedResponse.trim()) return j.mergedResponse;
  const c = j.content;
  if (c && Array.isArray(c.parts)) return c.parts.map(x => x.text || '').join('');
  if (Array.isArray(c)) return c.map(x => (x.parts || []).map(y => y.text || '').join('') || x.text || '').join('');
  if (typeof c === 'string') return c;
  if (Array.isArray(j.candidates) && j.candidates[0] && j.candidates[0].content) return (j.candidates[0].content.parts || []).map(x => x.text || '').join('');
  return String(j.text || j.output || j.response || '');
};
const parseJson = (t) => {
  let x = String(t || '').trim().replace(/^\x60{3}(?:json)?\s*/i, '').replace(/\x60{3}\s*$/, '').trim();
  const a = x.indexOf('{'), b = x.lastIndexOf('}');
  if (a >= 0 && b > a) {
    try {
      const o = JSON.parse(x.slice(a, b + 1));
      return { summary: String(o.summary || ''), mainPoints: Array.isArray(o.mainPoints) ? o.mainPoints.map(String) : [], keyTakeaways: Array.isArray(o.keyTakeaways) ? o.keyTakeaways.map(String) : [] };
    } catch (e) {}
  }
  return { summary: x, mainPoints: [], keyTakeaways: [] };
};
const describe = (msg) => {
  msg = String(msg || '');
  if (/API key|401|403|permission|unauthori|credential/i.test(msg)) return 'Gemini rejected the API credential. Check the Google Gemini credential in n8n.';
  if (/429|quota|rate|exhausted|credits/i.test(msg)) return 'Gemini quota or rate limit reached. Please wait a minute and try again.';
  if (/503|overloaded|unavailable/i.test(msg)) return 'Gemini is temporarily overloaded. Please try again in a minute.';
  if (/safety|blocked/i.test(msg)) return 'Gemini blocked this content for safety reasons, so no summary could be produced.';
  if (/timeout|ETIMEDOUT|ECONNRESET/i.test(msg)) return 'The Gemini request timed out. Please try again.';
  return 'Summarization with Gemini failed: ' + msg;
};
const items = $input.all();
const sections = [];
const errors = [];
for (const i of items) {
  const j = i.json || {};
  const t = getText(j);
  if (t && t.trim()) sections.push(parseJson(t));
  else if (j.error) errors.push(typeof j.error === 'string' ? j.error : (j.error.message || JSON.stringify(j.error)));
  else errors.push('Empty response from Gemini.');
}
if (!sections.length) {
  return [{ json: { status: 'error', error: describe(errors[0]), sections: [], combinedText: '', needsFinalPass: false } }];
}
const combinedText = sections.map((x, n) => 'Section ' + (n + 1) + ' summary: ' + x.summary + '\nMain points: ' + x.mainPoints.join(' | ') + '\nTakeaways: ' + x.keyTakeaways.join(' | ')).join('\n\n');
return [{ json: {
  status: 'ok',
  error: '',
  sections: sections,
  combinedText: combinedText,
  needsFinalPass: sections.length > 1,
  failedChunks: errors.length,
  totalChunks: items.length,
} }];

