const r = $('Telegram Summary Ready?').first().json;
const chatId = $('Telegram Trigger').first().json.message.chat.id;
const LIMIT = 3500; // leaves room for headings and HTML escaping
const MAX_TRANSCRIPT_MESSAGES = 12; // about 40,000 characters; avoids flooding the chat
const esc = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
