const header = '<b>' + esc(r.title || 'Your video') + '</b>\nSource: ' + esc(r.source) + '\nStatus: ' + esc(r.processingStatus || 'Completed') + ((r.warnings || []).length ? '\nNote: ' + esc(r.warnings.join(' ')) : '');
const summaryParts = splitText(r.summary);
messages.push(header + '\n\n<b>Summary</b>\n' + esc(summaryParts[0] || ''));
summaryParts.slice(1).forEach(p => messages.push(esc(p)));
const points = (r.keyPoints || []).map((p, i) => (i + 1) + '. ' + p).join('\n');
splitText(points).forEach((p, i) => messages.push((i === 0 ? '<b>Main points</b>\n' : '') + esc(p)));
const takeaways = (r.keyTakeaways || []).map((p, i) => (i + 1) + '. ' + p).join('\n');
if (takeaways) splitText(takeaways).forEach((p, i) => messages.push((i === 0 ? '<b>Key takeaways</b>\n' : '') + esc(p)));
const transcriptParts = splitText(r.transcript);
const shown = transcriptParts.slice(0, MAX_TRANSCRIPT_MESSAGES);
shown.forEach((p, i) => messages.push('<b>Transcript (' + (i + 1) + '/' + shown.length + ')</b>\n' + esc(p)));
if (transcriptParts.length > shown.length) {
  messages.push('The transcript is very long, so only the first ' + shown.length + ' parts were sent here. The summary and your questions still use the full transcript.');
}
messages.push('You can now ask me questions about this video. Just type your question. Send a new link or video at any time to switch videos.');
return messages.map(text => ({ json: { chatId: chatId, text: text } }));

