// Maps the Whisper result (or an upstream validation error) to the shared shape.
const res = $input.first().json;
const fileName = String(res.fileName || $('Validate Input').first().json.fileName || 'Uploaded video');
const out = (status, transcript, error) => [{ json: {
  status: status, sourceType: 'upload', title: fileName, source: 'Uploaded file: ' + fileName,
  transcript: transcript, error: error || '',
} }];
// False branch of "Valid MP4 Upload?": validation error from Validate Input
if (res.status === 'error') {
  return [{ json: { status: 'error', sourceType: res.sourceType, title: res.title || '', source: res.source || '', transcript: '', error: res.error } }];
}
if (res.error) {
  const msg = typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error));
  let friendly = 'Speech-to-text failed: ' + msg;
  if (/429|rate/i.test(msg)) friendly = 'The speech-to-text service is rate limited. Please wait a minute and try again.';
  else if (/413|too large|size/i.test(msg)) friendly = 'The file is too large for the speech-to-text service (25 MB limit).';
  else if (/format|decode|invalid file/i.test(msg)) friendly = 'The speech-to-text service could not read this MP4. It may be corrupted or use an unsupported codec.';
  else if (/401|api key|credential|credit/i.test(msg)) friendly = 'The speech-to-text credential is invalid or out of credits. Check the OpenAI credential in n8n.';
  return out('error', '', friendly);
}
const text = String(res.text || '').replace(/\s+/g, ' ').trim();
if (text.split(' ').filter(Boolean).length < 3) {
  return out('error', '', 'No speech was detected in this video, so there is nothing to summarize.');
}
return out('ok', text, '');

// Works out what the Telegram user sent: a link, an MP4 video, a question, or something we answer directly.
const msg = $input.first().json.message || {};
const chatId = msg.chat ? msg.chat.id : null;
const text = String(msg.text || msg.caption || '').trim();
const MAX_MB = 20; // Telegram bots cannot download files larger than 20 MB
const help = 'Hi! Send me a YouTube link or an MP4 video (up to 20 MB) and I will reply with the transcript and a summary. After that, just type any question about the video.';
const out = (route, extra) => [{ json: Object.assign({ route: route, chatId: chatId, text: text, replyText: '' }, extra || {}) }];

let file = null;
if (msg.video) file = { fileId: msg.video.file_id, size: msg.video.file_size || 0, mime: msg.video.mime_type || 'video/mp4', name: msg.video.file_name || 'telegram-video.mp4' };
else if (msg.video_note) file = { fileId: msg.video_note.file_id, size: msg.video_note.file_size || 0, mime: 'video/mp4', name: 'video-note.mp4' };
else if (msg.document) file = { fileId: msg.document.file_id, size: msg.document.file_size || 0, mime: msg.document.mime_type || '', name: msg.document.file_name || '' };

if (file) {
  const isMp4 = String(file.mime).toLowerCase() === 'video/mp4' || /\.mp4$/i.test(file.name);
  if (!isMp4) {
    return out('reply', { replyText: 'Sorry, I can only process MP4 videos. This file looks like ' + (file.mime || file.name || 'another format') + '. Please convert it to MP4, or send me a YouTube link instead.' });
  }
  const sizeMb = file.size / (1024 * 1024);
  if (sizeMb > MAX_MB) {
    return out('reply', { replyText: 'This video is ' + sizeMb.toFixed(1) + ' MB. Telegram bots can only download files up to 20 MB. Please trim or compress it, or upload it to YouTube and send me the link.' });
  }
  const name = /\.mp4$/i.test(file.name) ? file.name : 'telegram-video.mp4';
  return out('video', { fileId: file.fileId, fileName: name, sizeMb: Number(sizeMb.toFixed(2)) });
}

if (!text) return out('reply', { replyText: 'I can only read text, YouTube links and MP4 videos. ' + help });
if (/^\/(start|help)\b/i.test(text)) return out('reply', { replyText: help });

const link = text.match(/https?:\/\/\S+|(?:www\.)?(?:youtube\.com|youtu\.be)\/\S+/i);
if (link) return out('link', { youtubeUrl: link[0] });

return out('question', { question: text });

